import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}

os.makedirs(UPLOAD_DIR, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def generate_job_id(filename):
    return hashlib.md5(f"{filename}{time.time()}".encode()).hexdigest()

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "healthy", "service": "doc-converter"})

@app.route('/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice"""
    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({"error": "Empty filename"}), 400

    if not allowed_file(file.filename):
        return jsonify({"error": "File type not allowed"}), 400

    # Get output format preference
    output_format = request.form.get('format', 'pdf')

    # Save uploaded file
    job_id = generate_job_id(file.filename)
    job_dir = os.path.join(UPLOAD_DIR, job_id)
    os.makedirs(job_dir, exist_ok=True)

    safe_name = secure_filename(file.filename)
    input_path = os.path.join(job_dir, safe_name)
    file.save(input_path)

    # Build conversion command
    # Using LibreOffice headless mode for conversion
    convert_cmd = f"libreoffice --headless --convert-to {output_format} --outdir {job_dir} {input_path}"

    try:
        result = subprocess.run(
            convert_cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=job_dir
        )

        if result.returncode != 0:
            app.logger.error(f"Conversion failed: {result.stderr.decode()}")
            return jsonify({"error": "Conversion failed", "details": result.stderr.decode()[:200]}), 500

        # Find the output file
        output_name = safe_name.rsplit('.', 1)[0] + '.' + output_format.split(':')[0]
        output_path = os.path.join(job_dir, output_name)

        if not os.path.exists(output_path):
            # Try to find any generated file
            generated = [f for f in os.listdir(job_dir) if f != safe_name]
            if generated:
                output_path = os.path.join(job_dir, generated[0])
            else:
                return jsonify({"error": "Output file not generated"}), 500

        return send_file(output_path, as_attachment=True, download_name=os.path.basename(output_path))

    except subprocess.TimeoutExpired:
        return jsonify({"error": "Conversion timed out"}), 504
    except Exception as e:
        app.logger.error(f"Unexpected error: {str(e)}")
        return jsonify({"error": "Internal error"}), 500
    finally:
        # Cleanup is handled by a separate cron job
        pass

@app.route('/batch', methods=['POST'])
def batch_convert():
    """Convert multiple documents - accepts JSON with URLs"""
    data = request.get_json()
    if not data or 'documents' not in data:
        return jsonify({"error": "No documents specified"}), 400

    # Validate document count
    if len(data['documents']) > 10:
        return jsonify({"error": "Maximum 10 documents per batch"}), 400

    results = []
    for doc in data['documents']:
        results.append({"url": doc.get('url', ''), "status": "queued"})

    return jsonify({"batch_id": generate_job_id("batch"), "results": results})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
